macro_rules! tests {
    () => {
        deps!();
        # [cfg (test)] mod tests { use alloc :: format ; use super :: * ; # [test] fn test_arithmetic_op () { let mut x = ByteSize :: mb (1) ; let y = ByteSize :: kb (100) ; assert_eq ! ((x + y) . as_u64 () , 1_100_000u64) ; assert_eq ! ((x - y) . as_u64 () , 900_000u64) ; assert_eq ! ((x + (100 * 1000) as u64) . as_u64 () , 1_100_000) ; assert_eq ! ((x * 2u64) . as_u64 () , 2_000_000) ; x += y ; assert_eq ! (x . as_u64 () , 1_100_000) ; x *= 2u64 ; assert_eq ! (x . as_u64 () , 2_200_000) ; } # [allow (clippy :: unnecessary_cast)] # [test] fn test_arithmetic_primitives () { let mut x = ByteSize :: mb (1) ; assert_eq ! ((x + MB as u64) . as_u64 () , 2_000_000) ; assert_eq ! ((x + MB as u32) . as_u64 () , 2_000_000) ; assert_eq ! ((x + KB as u16) . as_u64 () , 1_001_000) ; assert_eq ! ((x - MB as u64) . as_u64 () , 0) ; assert_eq ! ((x - MB as u32) . as_u64 () , 0) ; assert_eq ! ((x - KB as u32) . as_u64 () , 999_000) ; x += MB as u64 ; x += MB as u32 ; x += 10u16 ; x += 1u8 ; assert_eq ! (x . as_u64 () , 3_000_011) ; } # [test] fn test_comparison () { assert ! (ByteSize :: mb (1) == ByteSize :: kb (1000)) ; assert ! (ByteSize :: mib (1) == ByteSize :: kib (1024)) ; assert ! (ByteSize :: mb (1) != ByteSize :: kib (1024)) ; assert ! (ByteSize :: mb (1) < ByteSize :: kib (1024)) ; assert ! (ByteSize :: b (0) < ByteSize :: tib (1)) ; assert ! (ByteSize :: pib (1) < ByteSize :: eb (1)) ; } # [test] fn as_unit_conversions () { assert_eq ! (41992187.5 , ByteSize :: gb (43) . as_kib ()) ; assert_eq ! (0.028311552 , ByteSize :: mib (27) . as_gb ()) ; assert_eq ! (0.0380859375 , ByteSize :: tib (39) . as_pib ()) ; assert_eq ! (961.482752 , ByteSize :: kib (938948) . as_mb ()) ; assert_eq ! (4.195428726649908 , ByteSize :: pb (4837) . as_eib ()) ; assert_eq ! (2.613772153284117 , ByteSize :: b (2873872874893) . as_tib ()) ; } # [track_caller] fn assert_display (expected : & str , b : ByteSize) { assert_eq ! (expected , format ! ("{b}")) ; } # [test] fn test_display () { assert_display ("215 B" , ByteSize :: b (215)) ; assert_display ("1.0 KiB" , ByteSize :: kib (1)) ; assert_display ("301.0 KiB" , ByteSize :: kib (301)) ; assert_display ("419.0 MiB" , ByteSize :: mib (419)) ; assert_display ("518.0 GiB" , ByteSize :: gib (518)) ; assert_display ("815.0 TiB" , ByteSize :: tib (815)) ; assert_display ("609.0 PiB" , ByteSize :: pib (609)) ; assert_display ("15.0 EiB" , ByteSize :: eib (15)) ; } # [test] fn test_display_alignment () { assert_eq ! ("|357 B     |" , format ! ("|{:10}|" , ByteSize (357))) ; assert_eq ! ("|     357 B|" , format ! ("|{:>10}|" , ByteSize (357))) ; assert_eq ! ("|357 B     |" , format ! ("|{:<10}|" , ByteSize (357))) ; assert_eq ! ("|  357 B   |" , format ! ("|{:^10}|" , ByteSize (357))) ; assert_eq ! ("|-----357 B|" , format ! ("|{:->10}|" , ByteSize (357))) ; assert_eq ! ("|357 B-----|" , format ! ("|{:-<10}|" , ByteSize (357))) ; assert_eq ! ("|--357 B---|" , format ! ("|{:-^10}|" , ByteSize (357))) ; } # [test] fn test_default () { assert_eq ! (ByteSize :: b (0) , ByteSize :: default ()) ; } }
    };
}

